<?php
require_once __DIR__ . '/include/config.php';
require_once __DIR__ . '/include/notifications.php';
hms_start_session();
$role = (string)($_SESSION['role'] ?? '');
if (!in_array($role, ['patient','doctor','admin'], true) || (int)($_SESSION['id'] ?? 0) < 1) { header('Location: ' . hms_base_url() . '/hms/user-login.php'); exit; }
$userId = (int)$_SESSION['id'];
if (!hms_notifications_ready($con)) exit('Notifications are not enabled. Apply SQL File/migrations/006_notifications.sql first.');
if ($_SERVER['REQUEST_METHOD'] === 'POST') { hms_verify_csrf(); $id = filter_var($_POST['notification_id'] ?? null, FILTER_VALIDATE_INT); if ($id) hms_db_query($con, 'UPDATE notifications SET read_at=COALESCE(read_at,NOW()) WHERE id=? AND recipient_role=? AND recipient_id=?', [$id,$role,$userId]); elseif (($_POST['action'] ?? '') === 'read_all') hms_db_query($con, 'UPDATE notifications SET read_at=NOW() WHERE recipient_role=? AND recipient_id=? AND read_at IS NULL', [$role,$userId]); header('Location: notifications.php'); exit; }
$page = max(1, (int)($_GET['page'] ?? 1)); $perPage = 20; $offset = ($page-1)*$perPage;
$total = (int)(hms_db_query($con, 'SELECT COUNT(*) total FROM notifications WHERE recipient_role=? AND recipient_id=?', [$role,$userId])->fetch_assoc()['total'] ?? 0);
$rows = hms_db_query($con, 'SELECT * FROM notifications WHERE recipient_role=? AND recipient_id=? ORDER BY id DESC LIMIT ? OFFSET ?', [$role,$userId,$perPage,$offset]);
$unread = hms_unread_notification_count($con,$role,$userId); $prefix = $role==='admin'?'admin/':($role==='doctor'?'doctor/':''); $sharedPrefix = $prefix === '' ? '' : '../';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications · MedTech</title><link rel="stylesheet" href="<?=hms_h($prefix)?>vendor/bootstrap/css/bootstrap.min.css"><link rel="stylesheet" href="<?=hms_h($prefix)?>vendor/fontawesome/css/font-awesome.min.css"><link rel="stylesheet" href="<?=hms_h($prefix)?>assets/css/styles.css"><link rel="stylesheet" href="<?=hms_h($prefix)?>assets/css/themes/theme-1.css"><link rel="stylesheet" href="<?=hms_h($sharedPrefix)?>assets/css/medtech-app.css"><link rel="stylesheet" href="<?=hms_h($sharedPrefix)?>assets/css/medtech-enterprise.css"><style>.mt-notice{display:flex;align-items:center;gap:14px;padding:16px;margin-bottom:9px;background:#fff;border:1px solid var(--mt-border);border-left:4px solid #d7e3df;border-radius:5px}.mt-notice.unread{border-left-color:var(--mt-primary);background:#fbfefd}.mt-notice p{margin:2px 0 0;color:var(--mt-muted)}.mt-notice .mt-notice-body{flex:1}.mt-notice time{font-size:10px;color:var(--mt-muted)}.mt-notice form{margin:0}.mt-notice-actions{display:flex;gap:10px;align-items:center}</style></head><body><div id="app"><?php if($role==='admin') include __DIR__.'/admin/include/sidebar.php'; elseif($role==='doctor') include __DIR__.'/doctor/include/sidebar.php'; else include __DIR__.'/include/sidebar.php'; ?><div class="app-content"><?php if($role==='admin') include __DIR__.'/admin/include/header.php'; elseif($role==='doctor') include __DIR__.'/doctor/include/header.php'; else include __DIR__.'/include/header.php'; ?><main class="main-content"><div class="wrap-content container"><section id="page-title"><h1 class="mainTitle">Notifications</h1><p class="text-muted"><?=$unread?> unread notification<?= $unread===1?'':'s' ?></p></section><div class="medtech-report-panel"><form method="post" class="pull-right"><?=hms_csrf_field()?><input type="hidden" name="action" value="read_all"><button class="btn btn-default btn-sm" <?=$unread?'':'disabled'?>>Mark all read</button></form><p>Updates about your appointments and hospital activity.</p></div><?php if($rows->num_rows):while($row=$rows->fetch_assoc()):$target=hms_notification_link($row,$role);?><article class="mt-notice <?=$row['read_at']?'':'unread'?>"><i class="fa fa-bell-o"></i><div class="mt-notice-body"><strong><?=hms_h($row['notification_type'])?></strong><p><?=hms_h($row['message'])?></p></div><time><?=hms_h($row['created_at'])?></time><div class="mt-notice-actions"><?php if($target!==''):?><a class="btn btn-primary btn-sm" href="<?=hms_h($target)?>">Open</a><?php endif;?><?php if(!$row['read_at']):?><form method="post"><?=hms_csrf_field()?><input type="hidden" name="notification_id" value="<?=hms_h($row['id'])?>"><button class="btn btn-default btn-sm">Read</button></form><?php endif;?></div></article><?php endwhile;else:?><div class="medtech-empty-state"><i class="fa fa-bell-o"></i><strong>No notifications yet</strong><span>Updates will appear here when new activity occurs.</span></div><?php endif;?><?php if($total>$perPage):?><nav><ul class="pagination"><?php for($n=1;$n<=ceil($total/$perPage);$n++):?><li class="<?=$n===$page?'active':''?>"><a href="?page=<?=$n?>"><?=$n?></a></li><?php endfor;?></ul></nav><?php endif;?></div></main><?php if($role==='admin') include __DIR__.'/admin/include/footer.php'; elseif($role==='doctor') include __DIR__.'/doctor/include/footer.php'; else include __DIR__.'/include/footer.php'; ?></div></div></body></html>
